  it('post210: locks src/index.ts first/last/mid octets', () => { const d = sha256("src/index.ts"); expect(d.slice(0, 2)).toBe("7f"); expect(d.slice(-2)).toBe("72"); expect(d.slice(28, 36)).toBe("e2a20389"); });
  it('post210: locks src/index.ts HMAC post210/after-#210/leftover', () => { expect(hmacSha256("post210", "src/index.ts")).toBe("b1b696ac034ac32a86dbbcc45905bec7203bbeaca7fad6c1cf6aa8ce526a8924"); expect(hmacSha256("after-#210", "src/index.ts")).toBe("debe8d50a880323cf2289594bdb9bdf542c635bf6b5c66ceb663dea1e7c9e23e"); expect(hmacSha256("leftover", "src/index.ts")).toBe("268d5e353fd881bdd119b1f654cb291896d509e3f70768fde43a2bef6fdea2be"); });
